// The adopted R1 verifier (PREREG-PROOF-SIZE-2, 2026-10-19): the compact
// binary-multiproof format of `crate::compact`. These are the only R1
// verification entrypoints of a default build.
#[path="candidate.rs"]
pub mod candidate;
